def flags_a_ofertas(apps, schema_editor):
    """The listing's included-in-rent flags become the inclusions of each of its rental offers."""
    Inmueble = apps.get_model('base', 'Inmueble')
    Inclusiones = apps.get_model('base', 'InclusionesAlquiler')
    Oferta = apps.get_model('base', 'InmuebleModalidad')
    for inm in Inmueble.objects.filter(models.Q(gastos_comunidad_incluidos=True) | models.Q(ibi_incluido=True)):
        for oferta in Oferta.objects.filter(inmueble=inm, modalidad__unidad_precio='mensual'):
            Inclusiones.objects.get_or_create(oferta=oferta, defaults={
                'gastos_comunidad': inm.gastos_comunidad_incluidos, 'ibi': inm.ibi_incluido})


def ofertas_a_flags(apps, schema_editor):
    """Back to the listing: a flag is set when any of its rental offers includes the item."""
    Inclusiones = apps.get_model('base', 'InclusionesAlquiler')
    Inmueble = apps.get_model('base', 'Inmueble')
    for inc in Inclusiones.objects.select_related('oferta'):
        cambios = {}
        if inc.gastos_comunidad:
            cambios['gastos_comunidad_incluidos'] = True
        if inc.ibi:
            cambios['ibi_incluido'] = True
        if cambios:
            Inmueble.objects.filter(pk=inc.oferta.inmueble_id).update(**cambios)


